<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\TenantConfigWellcomeEmailVO;
use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Holder\TenantConfigWellcomeEmailAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigWellcomeEmailAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TenantConfigWellcomeEmailAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that getWellcomeEmail returns null on a freshly created holder.
         */
        public function testWellcomeEmailNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithTenantConfigWellcomeEmailAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isWellcomeEmailAssigned());
            $this->assertNull($holder->getWellcomeEmail());
        }
}
class ImplWithTenantConfigWellcomeEmailAttributeHolderUnitTest
{
  use TenantConfigWellcomeEmailAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedWellcomeEmailRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultWellcomeEmail();
    }}
